"""Clean up enum CHECK constraints in an autogenerated Alembic migration.

Autogenerate renders each enum CHECK twice, named after the enum type, which
clashes when a table has two columns of the same enum. This keeps one per
column, named ck_<table>_<column>, and drops the column-level create_constraint
so the constraint isn't created a third time. For op.add_column of an enum, it
adds an explicit create_check_constraint.

    python scripts/fix_enum_checks.py migrations/versions/<file>.py
"""

import re
import sys
from pathlib import Path


def fix(source: str) -> str:
    out, table, seen = [], None, set()
    for line in source.splitlines():
        if m := re.match(r"\s*op\.create_table\('(\w+)'", line):
            table, seen = m.group(1), set()
        if a := re.match(r"(\s*)op\.add_column\('(\w+)', sa\.Column\('(\w+)', sa\.Enum\(([^)]*?), name=.*create_constraint=True", line):
            # Added columns get no CHECK from autogenerate once the flag is gone; add it explicitly.
            indent, tbl, col, values = a.groups()
            out.append(line.replace(", create_constraint=True", ""))
            out.append(f'{indent}op.create_check_constraint("ck_{tbl}_{col}", "{tbl}", "{col} IN ({values})")')
            continue
        line = line.replace(", create_constraint=True", "")
        if c := re.match(r"(\s*)sa\.CheckConstraint\(\"(\w+) IN (.*)\", name='\w+'\),$", line):
            indent, col, values = c.groups()
            if col in seen:
                continue
            seen.add(col)
            line = f'{indent}sa.CheckConstraint("{col} IN {values}", name="ck_{table}_{col}"),'
        out.append(line)
    return "\n".join(out) + "\n"


if __name__ == "__main__":
    for arg in sys.argv[1:]:
        path = Path(arg)
        path.write_text(fix(path.read_text()))
        print(f"fixed {path}")
